/// <summary>
/// Defines ABN validation failure types logged into AppInsights.
/// </summary>
public final class METABNValidationFailureTypes
{
    public const str None               = 'None';
    public const str Timeout            = 'Timeout';
    public const str ServiceError       = 'ServiceError';
    public const str UnhandledException = 'UnhandledException';
    public const str UpdateError        = 'UpdateError';
}
